#!/usr/bin/env python3
"""Build the offline Qwen persona vector map from frozen radius artifacts."""
import csv,json,html
from pathlib import Path
import numpy as np
HERE=Path(__file__).parent
OUT=HERE/'persona_vector_map.html'
rows=list(csv.DictReader((HERE/'radius_candidates.csv').open()))
roles=np.load(HERE/'qwen_mean_roles.npz',allow_pickle=True)
geo=np.load(HERE/'radius_geometry.npz',allow_pickle=True)
personas=[str(x) for x in roles['personas']]
coords=(roles['vectors'].astype(float)-geo['pc_mean']) @ geo['pc_basis']
assert len(personas)==275 and len(set(personas))==275 and np.isfinite(coords).all()
assert len(rows)==11550 and {r['persona'] for r in rows}==set(personas)
for r in rows:
 for k,v in r.items():
  if k not in ('persona','candidate','path_outside_reference_support'):
   assert np.isfinite(float(v)),(k,v)
# store only fields used by viewer
fields=['persona','dimensions','radius','radius_fraction_of_median_fifth_neighbor','candidate','bigfive_start','direct_start','bigfive_end','direct_end','delta_bigfive','delta_direct','bigfive_gain_fraction','direct_gain_fraction','endpoint_fifth_neighbor_distance','path_max_fifth_neighbor_distance','support_threshold','path_outside_reference_support','delta_PC1','delta_PC2','delta_PC3','delta_PC4','delta_PC5','delta_C1_sd','delta_C2_sd','delta_C3_sd','delta_C4_sd','delta_C5_sd']
compact=[{k:(r[k] if k in ('persona','candidate','path_outside_reference_support') else float(r[k])) for k in fields} for r in rows]
data={'schema':'qwen-persona-vector-map-v1','personas':personas,'coords':coords.tolist(),'candidates':compact,'labels':['expressive intensity','abstract reflection','compassionate understanding','integrative imagination','decisive commitment']}
payload=json.dumps(data,separators=(',',':')).replace('</','<\\/')
page='''<!doctype html><meta charset="utf-8"><title>Qwen Persona Vector Map</title><style>
body{margin:0;background:#10151d;color:#e8edf4;font:14px system-ui;display:grid;grid-template-columns:300px 1fr;min-height:100vh}aside{padding:18px;background:#18212d;border-right:1px solid #324154}h1{font-size:20px;margin:0 0 8px}label{display:block;margin:12px 0 4px;color:#b8c8da}select,input{width:100%;box-sizing:border-box;padding:7px;background:#0d131b;color:#edf4ff;border:1px solid #42546a;border-radius:4px}canvas{width:100%;height:calc(100vh - 0px);display:block}#detail{white-space:pre-wrap;line-height:1.5;font-size:12px;background:#101720;padding:10px;margin-top:14px;border-radius:5px}.note{font-size:12px;line-height:1.4;color:#b8c8da}.key{color:#7dd3fc}button{margin-top:12px;padding:7px;background:#24364a;color:white;border:1px solid #54718d;border-radius:4px}</style><aside><h1>Qwen persona vector map</h1><p class=note>Frozen geometric readout changes, not established behavioral interventions or human treatment effects.</p><label>Spatial view</label><select id=view><option value=3>3D: PC1 × PC2 × PC3</option><option value=12>2D: PC1 × PC2</option><option value=13>2D: PC1 × PC3</option><option value=23>2D: PC2 × PC3</option></select><label>Zoom</label><input id=zoom type=range min=0.5 max=2.5 step=0.05 value=1 aria-label="Map zoom"><label>Movement space</label><select id=dims><option value=5>5 PCs</option><option value=3>3 PCs</option></select><label>Radius</label><select id=radius><option value=4.177581924285131>0.25× fifth-neighbor radius</option><option selected value=8.355163848570262>0.5× fifth-neighbor radius</option><option value=16.710327697140524>1.0× fifth-neighbor radius</option></select><label>Candidate</label><select id=cand></select><label>Display-length gain mapping</label><select id=gain><option value=bigfive>Big Five-associated gain</option><option value=direct>Direct-trait gain</option><option value=compromise>Minimum of both gain fractions</option></select><label>Select persona</label><select id=persona></select><button id=reset>Reset 3D camera</button><p class=note><span class=key>Arrows:</span> direction is the saved PC displacement; display length is global min-max normalization of the selected gain across the currently relevant frozen result set. Details retain literal PC displacement.</p><div id=detail>Select a persona or click a point.</div></aside><canvas id=c></canvas><script id=data type=application/json>'''+payload+'''</script><script>
const D=JSON.parse(document.querySelector('#data').textContent),$=id=>document.getElementById(id),can=$('c'),ctx=can.getContext('2d');let yaw=.65,pitch=.45,zoom=1,drag=null;
const candidates=[...new Set(D.candidates.map(r=>r.candidate))];$('cand').innerHTML=candidates.map(x=>`<option ${x==='compromise'?'selected':''}>${x}</option>`).join('');$('persona').innerHTML=D.personas.map(x=>`<option>${x}</option>`).join('');
function pick(){let dim=+$('dims').value,rad=+$('radius').value,ca=$('cand').value;return D.candidates.filter(r=>r.dimensions===dim&&Math.abs(r.radius-rad)<1e-9&&r.candidate===ca)}
function proj(v){let mode=$('view').value;if(mode!=='3'){let a=mode[0]-1,b=mode[1]-1;return [v[a],v[b],0]}let x=v[0]*Math.cos(yaw)-v[1]*Math.sin(yaw),y=v[0]*Math.sin(yaw)+v[1]*Math.cos(yaw),z=v[2];return [x,y*Math.cos(pitch)-z*Math.sin(pitch),y*Math.sin(pitch)+z*Math.cos(pitch)]}
function render(){can.width=can.clientWidth*devicePixelRatio;can.height=can.clientHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);let w=can.clientWidth,h=can.clientHeight,rows=pick(),by=new Map(rows.map(r=>[r.persona,r])),m=$('gain').value,vals=rows.map(r=>m==='bigfive'?r.delta_bigfive:m==='direct'?r.delta_direct:Math.min(r.bigfive_gain_fraction,r.direct_gain_fraction)),lo=Math.min(...vals),hi=Math.max(...vals),ps=D.coords.map(proj),range=Math.max(...ps.flatMap(p=>[Math.abs(p[0]),Math.abs(p[1])]))||1,s=zoom*0.42*Math.min(w,h)/range,center=[w*.5,h*.5],selected=$('persona').value;ctx.fillStyle='#10151d';ctx.fillRect(0,0,w,h);ctx.fillStyle='#7890a8';ctx.fillText('Drag to rotate in 3D · click a persona · arrow length is normalized gain',16,22);let mode=$('view').value,names=mode==='3'?['PC1','PC2','PC3']:[`PC${mode[0]}`,`PC${mode[1]}`];ctx.strokeStyle='#52657b';ctx.fillStyle='#b9d8f0';ctx.lineWidth=1; if(mode!=='3'){ctx.beginPath();ctx.moveTo(20,center[1]);ctx.lineTo(w-20,center[1]);ctx.moveTo(center[0],40);ctx.lineTo(center[0],h-20);ctx.stroke();ctx.fillText(names[0]+' →',w-64,center[1]-8);ctx.fillText(names[1]+' ↑',center[0]+8,54)}else{for(let a=0;a<3;a++){let u=[0,0,0];u[a]=range*.22;let t=proj(u),X=center[0]+t[0]*s,Y=center[1]-t[1]*s;ctx.beginPath();ctx.moveTo(center[0],center[1]);ctx.lineTo(X,Y);ctx.stroke();ctx.fillText(names[a],X+5,Y-5)}}for(let i=0;i<D.personas.length;i++){let p=ps[i],r=by.get(D.personas[i]),dx=[r.delta_PC1,r.delta_PC2,r.delta_PC3,0,0],q=proj(D.coords[i].map((x,j)=>x+dx[j])),gain=vals[i],mag=.2+.8*(gain-lo)/(hi-lo||1),ex=p[0]+(q[0]-p[0])*mag,ey=p[1]+(q[1]-p[1])*mag,x=center[0]+p[0]*s,y=center[1]-p[1]*s,X=center[0]+ex*s,Y=center[1]-ey*s;ctx.strokeStyle=r.path_outside_reference_support==='True'?'#f59e0b':'#45c5f5';ctx.globalAlpha=.48;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(X,Y);ctx.stroke();ctx.beginPath();ctx.moveTo(X,Y);ctx.lineTo(X-5,Y+3);ctx.lineTo(X-2,Y-5);ctx.fillStyle=ctx.strokeStyle;ctx.fill();ctx.globalAlpha=1;ctx.beginPath();ctx.arc(x,y,D.personas[i]===selected?5:2.4,0,7);ctx.fillStyle=D.personas[i]===selected?'#fff':'#d6e6f5';ctx.fill()}let r=by.get(selected),i=D.personas.indexOf(selected);if(r){$('detail').textContent=`${selected}\nCandidate: ${r.candidate}; radius ${r.radius_fraction_of_median_fifth_neighbor}×\nStart PC1–PC3: ${D.coords[i].slice(0,3).map(x=>x.toFixed(3)).join(', ')}\nLiteral ΔPC1–PC5: ${[r.delta_PC1,r.delta_PC2,r.delta_PC3,r.delta_PC4,r.delta_PC5].map(x=>x.toFixed(4)).join(', ')}\nBig Five: ${r.bigfive_start.toFixed(4)} → ${r.bigfive_end.toFixed(4)} (Δ ${r.delta_bigfive.toFixed(4)}; fraction ${r.bigfive_gain_fraction.toFixed(4)})\nDirect trait: ${r.direct_start.toFixed(4)} → ${r.direct_end.toFixed(4)} (Δ ${r.delta_direct.toFixed(4)}; fraction ${r.direct_gain_fraction.toFixed(4)})\nC1–C5 SD changes: ${[r.delta_C1_sd,r.delta_C2_sd,r.delta_C3_sd,r.delta_C4_sd,r.delta_C5_sd].map(x=>x.toFixed(4)).join(', ')}\nSupport warning: ${r.path_outside_reference_support}; display normalization [${lo.toFixed(4)}, ${hi.toFixed(4)}]`}}
for(const id of ['view','dims','radius','cand','gain','persona']) $(id).onchange=render;$('zoom').oninput=e=>{zoom=+e.target.value;render()};$('reset').onclick=()=>{yaw=.65;pitch=.45;zoom=1;$('zoom').value=1;render()};can.onpointerdown=e=>drag=[e.clientX,e.clientY];can.onpointermove=e=>{if(drag&&$('view').value==='3'){yaw+=(e.clientX-drag[0])*.01;pitch+=(e.clientY-drag[1])*.01;drag=[e.clientX,e.clientY];render()}};can.onpointerup=()=>drag=null;addEventListener('resize',render);render();</script>'''
OUT.write_text(page)
print(OUT,OUT.stat().st_size)
